import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1000000007;

    static long modPow(long base, long exp, long modulus) {
        long result = 1;
        long cur = base % modulus;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * cur) % modulus;
            }
            cur = (cur * cur) % modulus;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long n = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());

        if (m == 0) {
            System.out.println(modPow(n, n - 1, MOD));
        } else if (m == 1) {
            System.out.println(modPow(n, n, MOD));
        } else {
            long[] parent = new long[(int) n + 1];
            int[] rank = new int[(int) n + 1];
            for (int i = 0; i <= n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }

            // find function with path compression
            LongUnaryOperator findp = new LongUnaryOperator() {
                public long applyAsLong(long x) {
                    while (parent[(int) x] != x) {
                        parent[(int) x] = parent[(int) parent[(int) x]];
                        x = parent[(int) x];
                    }
                    return x;
                }
            };

            // union function
            BiConsumer<Long, Long> unite = (a, b) -> {
                long pa = findp.applyAsLong(a);
                long pb = findp.applyAsLong(b);
                if (pa != pb) {
                    if (rank[(int) pa] >= rank[(int) pb]) {
                        parent[(int) pb] = pa;
                        if (rank[(int) pa] == rank[(int) pb]) {
                            rank[(int) pa]++;
                        }
                    } else {
                        parent[(int) pa] = pb;
                    }
                }
            };

            for (long i = 1; i < n; i++) {
                long b = (i * m) % n;
                unite.accept(i, b);
            }

            Set<Long> components = new HashSet<>();
            for (long i = 1; i < n; i++) {
                components.add(findp.applyAsLong(i));
            }
            long size = components.size();
            System.out.println(modPow(n, size, MOD));
        }
    }
}

